import type { Metadata } from "next";
import { notFound } from "next/navigation";
import { connection } from "next/server";
import { ADS_BOT_TERMS } from "@/lib/legal/adsBotTermsDoc";
import { TermsDocument } from "@/components/legal/TermsDocument";
import { adsBotTermsPublished } from "@/lib/google-ads/adsBotTermsPublished";

// Ads Bot terms of use. HEBREW-SAFETY: this file holds zero Hebrew bytes; every rendered string comes from
// ADS_BOT_TERMS, generated byte-exact from docs/legal/ads-bot-terms-of-use.md (scripts/build-ads-bot-terms.mjs).
// UNPUBLISHED until ADS_BOT_TERMS_PUBLISHED === 'true' (read at request time: connection()). Same renderer and robots
// as /site-bot/terms (noindex, follow; not in the sitemap). The checkout consent links here (ADS_BOT_TERMS_PATH).

export const metadata: Metadata = {
  title: ADS_BOT_TERMS.title,
  robots: { index: false, follow: true },
};

export default async function AdsBotTermsPage() {
  await connection();
  if (!adsBotTermsPublished()) notFound();
  return <TermsDocument doc={ADS_BOT_TERMS} docId="ads-bot-terms" />;
}
